-- =============================================================================
-- SEA-V -- seed the shared yacht directory from Wikidata (v610)
-- =============================================================================
-- Jack, 2026-11-05: "find a list of superyachts for the yacht directory and add some".
-- Source: Wikidata (CC0), items typed yacht, motor yacht, luxury yacht, sailing yacht or
-- royal yacht with an IMO number, fetched 2026-11-05. Kept: valid IMO check digit, one
-- clear name, 24 m and over, service from 1960. Removed by hand as not yachts or not
-- named: NOAAS Pierce, Sea-Watch 3, Dong Hai Jiu 203, Sindhu Sankalp, Cape Race, Kroeger 13684.
-- MMSI dropped where not 9 digits or shared by two entries. Owners are not stored.
-- Community data, so details can be out of date. Existing entries are never overwritten.
-- APPLIED 2026-11-05 (migration vessel_directory_seed_wikidata).
-- To undo: delete from public.vessel_directory where source = 'wikidata'
--   and not exists (select 1 from public.vessels v where v.directory_id = vessel_directory.id);
-- =============================================================================

alter table public.vessel_directory add column if not exists source text;

insert into public.vessel_directory (name, imo, mmsi, call_sign, flag, gt, vessel_length, builder, year_built, source)
select r->>0, r->>1, r->>2, r->>3, r->>4, r->>5, r->>6, r->>7, r->>8, 'wikidata'
